// Original, unmodified v1.43 OGG assets. Event mappings follow data/sounds.txt.
const ROOT='./assets/classic/audio/';
const MUSIC=['defconmus1a','defconmus1b','defconmus1c','defconmus1d','defconmus1e','defconmus1f','defconmus1g','defconmus3a','defconmus3b','defconmus3c','defconmus3d','defconmus4a','defconmus4b','defconmus4c','defconmus2a','defconmus2b','defconmus2c','defconmus2d','defconmus2e','defconmus2f','defcon5e','defcon5d','defcon5c','defcon5b','defcon5a','defcon6a','defcon6b','defcon6c'];
const SPOTS=['boots_verb','door_closeverb','door_openverb','gasmask_verb','lords_prayer','mancough_verb','paper_rustle_verb','printer_verb','radio_tuningverb','telemetry1verb','telemetry2verb','telemetry3verb','teleprinter_verb','womancough_verb','womancry2_verb'];
export class Soundscape {
 constructor(){this.ctx=null;this.master=null;this.enabled=false;this.volume=.4;this.musicVolume=.55;this.voice=true;this.nodes=new Set();this.buffers=new Map();this.musicIndex=0;this.media=[];this.timers=[];this.errors=[];this.firstLaunch=false;this.music=null;this.ambience=null;}
 async init(){if(this.ctx)return;this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=this.volume;this.master.connect(this.ctx.destination);this.music=new Audio(ROOT+MUSIC[0]+'.ogg');this.music.preload='metadata';this.music.onended=()=>{this.musicIndex=(this.musicIndex+1)%MUSIC.length;this.music.src=ROOT+MUSIC[this.musicIndex]+'.ogg';if(this.enabled)this.music.play().catch(e=>this.errors.push(e.message));};this.music.addEventListener('error',()=>this.errors.push('Music file could not be decoded'));const musicSource=this.ctx.createMediaElementSource(this.music);this.musicGain=this.ctx.createGain();this.musicGain.gain.value=this.musicVolume;musicSource.connect(this.musicGain).connect(this.master);this.ambience=new Audio(ROOT+'bunker1.ogg');this.ambience.loop=true;this.ambience.preload='metadata';const ambientSource=this.ctx.createMediaElementSource(this.ambience);this.ambientGain=this.ctx.createGain();this.ambientGain.gain.value=.16;ambientSource.connect(this.ambientGain).connect(this.master);this.media=[this.music,this.ambience];}
 async toggle(){if(this.enabled){this.enabled=false;this.media.forEach(a=>a.pause());this.timers.forEach(clearTimeout);this.timers=[];this.master?.gain.setTargetAtTime(0,this.ctx.currentTime,.15);return false;}try{await this.init();await this.ctx.resume();this.enabled=true;this.setVolume(this.volume);await this.music.play();this.ambience.play().catch(e=>this.errors.push(e.message));this.scheduleSpot();this.effect('select');return true;}catch(e){this.enabled=false;this.errors.push(e.message);this.media.forEach(a=>a.pause());return false;}}
 setVolume(v){this.volume=Math.max(0,Math.min(1,v));if(this.master)this.master.gain.setTargetAtTime(this.enabled?this.volume:0,this.ctx.currentTime,.12);}
 setMusicVolume(v){this.musicVolume=Math.max(0,Math.min(1,v));this.musicGain?.gain.setTargetAtTime(this.musicVolume,this.ctx.currentTime,.12);}
 async sample(name,gain=.5,rate=1){if(!this.enabled)return;try{if(!this.buffers.has(name)){this.buffers.set(name,fetch(ROOT+name+'.ogg').then(r=>{if(!r.ok)throw Error(`Audio unavailable: ${name}`);return r.arrayBuffer();}).then(b=>this.ctx.decodeAudioData(b)));}const buffer=await this.buffers.get(name);if(!this.enabled)return;const source=this.ctx.createBufferSource(),amp=this.ctx.createGain();source.buffer=buffer;source.playbackRate.value=rate;amp.gain.value=gain;source.connect(amp).connect(this.master);this.nodes.add(source);source.onended=()=>{source.disconnect();amp.disconnect();this.nodes.delete(source);};source.start();}catch(e){this.errors.push(e.message);}}
 scheduleSpot(){const timer=setTimeout(()=>{if(!this.enabled)return;this.sample(SPOTS[Math.floor(Math.random()*SPOTS.length)],.15);this.scheduleSpot();},9000+Math.random()*6000);this.timers.push(timer);}
 // The classic recordings replace the previous synthesized radio narration.
 speak(){}
 effect(type){if(!this.enabled)return;switch(type){case 'select':this.sample('rollover1a_wet',.28,.39);break;case 'order':this.sample('hilite1alt',.38,.9);break;case 'error':this.sample('Beep_Harsh_Malfunction',.5,.61);break;case 'alarm':this.sample('defconstage',.7,.39);break;case 'enemylaunch':if(!this.firstLaunch){this.firstLaunch=true;this.sample('enemylaunch2',.8,.55);}break;case 'launch':break;case 'nuclear':this.sample('nuke_rumble'+(1+Math.floor(Math.random()*3)),.65);this.sample(['fallout','fallout2','fallout3','fallout4','fallout5','fallout7','fallout8','fallout9','fallout10','fallout11','fallout12','fallout13'][Math.floor(Math.random()*12)],.65,.67+Math.random()*.32);break;case 'sonar':this.sample(Math.random()<.5?'sonarpingnew1':'sonarpingnew2',.32);break;case 'depthcharge':this.sample('depthcharge',.35);break;case 'end':this.sample('gameover',.65,.47);break;}}
 get status(){return {enabled:this.enabled,music:this.music?.currentSrc||null,musicPlaying:!!this.music&&!this.music.paused,musicTime:this.music?.currentTime||0,errors:[...this.errors],originalFiles:true};}
}
